Warlock-p5c-close.manifest:
[package]
name = "warlock-app"
version = "0.1.0"
description = "Warlock workspace management application"
authors = ["Laughing Skull Enterprises"]
edition = "2024"
publish = false

[lib]
name = "warlock_app_lib"
crate-type = ["lib", "cdylib", "staticlib"]

[build-dependencies]
tauri-build = { version = "2.6.3", features = [] }

[dependencies]
aes-gcm = "0.10"
async-trait = "0.1"
base64 = "0.22"
futures-util = "0.3"
# Warlock ships against an explicit Reliquary compatibility revision. Use the local-dev wrapper in scripts/ instead of restoring an ambient sibling path dependency.
reliquary-memory = { git = "https://github.com/Lokee86/Reliquary.git", rev = "83b3ac87a80a4221039fa07d9722f5f8076464ba" }
# Keep the direct Arcana dependency on the exact revision that pinned Reliquary uses;
# both capabilities must resolve to one crate instance, not separate graph contracts.
arcana = { git = "https://github.com/Lokee86/lexicon-arcana.git", rev = "66b4e96ecf18cc79dfd6b1ea30232bef7c86bba3" }
reqwest = { version = "=0.12.23", default-features = false, features = ["blocking", "rustls-tls", "json", "stream"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
sha2 = "0.10"
tauri = { version = "2.11.5", features = [] }
tauri-plugin-dialog = "2.7.2"
open = { version = "5.4.3", features = ["shellexecute-on-windows"] }
tiktoken-rs = "0.12.0"
tokio = { version = "1", features = ["io-util", "macros", "net", "rt", "rt-multi-thread", "sync", "time"] }
tokio-util = { version = "0.7", features = ["io", "rt"] }
uuid = { version = "1", features = ["v4"] }
windows = { version = "0.61.3", features = ["Win32_Foundation", "Win32_System_Com", "Win32_UI_Shell"] }
zeroize = "1"

# Cargo patches are root-only: Reliquary's Lore dependency requires Lore's patched
# quinn-proto, so the application root repeats this build-only override. Warlock
# does not own Lore or Project Environment semantics.
[patch.crates-io]
quinn-proto = { path = "../vendor/quinn-proto" }

